#include <iostream>
#include <vector>

// 定义迷宫大小，+2 是为了加哨兵墙
const int MAX_M = 15;
const int MAX_N = 15;

// 全局变量
int maze[MAX_M + 2][MAX_N + 2]; // 迷宫地图，0为墙，1为路
int path[MAX_M * MAX_N][2];    // 记录路径，path[i][0]=row, path[i][1]=col
bool has_path = false;         // 是否找到至少一条路径的标志

// 按照题目要求的优先顺序：左、上、右、下
// dx, dy 分别对应行和列的变化
const int dx[] = {0, -1, 0, 1};
const int dy[] = {-1, 0, 1, 0};

// 深度优先搜索函数
// x, y: 当前位置坐标
// step: 当前是第几步（路径中点的个数）
// end_x, end_y: 终点坐标
void dfs(int x, int y, int step, int end_x, int end_y) {
    // 1. 检查是否到达终点
    if (x == end_x && y == end_y) {
        has_path = true;
        // 输出路径
        for (int i = 1; i < step; ++i) {
            std::cout << "(" << path[i][0] << "," << path[i][1] << ")";
            if (i < step - 1) {
                std::cout << "->";
            }
        }
        std::cout << std::endl;
        return; // 到达终点后，返回以寻找其他路径
    }

    // 2. 按照左、上、右、下的顺序探索
    for (int i = 0; i < 4; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        // 判断新位置是否可走
        if (maze[nx][ny] == 1) {
            // 做出选择
            maze[nx][ny] = 0; // 标记为已访问
            path[step][0] = nx;
            path[step][1] = ny;

            // 递归深入
            dfs(nx, ny, step + 1, end_x, end_y);

            // 撤销选择（回溯）
            maze[nx][ny] = 1; // 恢复为未访问状态
        }
    }
}

int main() {
    // 提高IO效率
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int m, n;
    std::cin >> m >> n;

    // 初始化迷宫，外围设为0（哨兵墙）
    for (int i = 0; i <= m + 1; ++i) {
        for (int j = 0; j <= n + 1; ++j) {
            maze[i][j] = 0;
        }
    }

    // 读入迷宫数据
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            std::cin >> maze[i][j];
        }
    }

    int start_x, start_y, end_x, end_y;
    std::cin >> start_x >> start_y;
    std::cin >> end_x >> end_y;

    // 如果起点或终点是墙，则无路可走
    if (maze[start_x][start_y] == 0 || maze[end_x][end_y] == 0) {
        std::cout << -1 << std::endl;
        return 0;
    }

    // 初始化路径和起点
    path[1][0] = start_x;
    path[1][1] = start_y;
    maze[start_x][start_y] = 0; // 标记起点为已访问

    // 从起点开始搜索
    dfs(start_x, start_y, 2, end_x, end_y);

    // 如果全程没找到路径
    if (!has_path) {
        std::cout << -1 << std::endl;
    }

    return 0;
}
